import type { Metadata } from "next";
import { routing, type AppLocale } from "@/i18n/routing";
import { brandName, siteUrl } from "./site";

/** Share-image pages generated by scripts/og-images.mjs into public/og/<locale>/. */
export type OgPage = "home" | "about" | "events" | "info" | "contact";

export const ogLocale: Record<AppLocale, string> = {
  ar: "ar_AE",
  en: "en_US",
};

/** Absolute URL of a page in a locale; `path` is "" for home or "/about". */
export const pageUrl = (locale: string, path = "") =>
  `${siteUrl}/${locale}${path}`;

type Options = {
  locale: AppLocale;
  /** "" for home, otherwise "/about", "/trips/slug"… */
  path: string;
  title: string;
  description: string;
  /** Share image path under public/, e.g. "/og/ar/about.png". */
  image: string;
  /** Use the title as-is (no "| brand" suffix). */
  absoluteTitle?: boolean;
};

/**
 * Per-page metadata: canonical + hreflang (ar, en, x-default → ar), Open Graph
 * and Twitter, all in one place so every page is consistent.
 */
export function pageMetadata({
  locale,
  path,
  title,
  description,
  image,
  absoluteTitle,
}: Options): Metadata {
  // Generated share images are 1200×630; other images (trip covers) keep their own size.
  const images = [
    image.startsWith("/og/")
      ? { url: image, width: 1200, height: 630, alt: title }
      : { url: image, alt: title },
  ];
  return {
    title: absoluteTitle ? { absolute: title } : title,
    description,
    alternates: {
      canonical: pageUrl(locale, path),
      languages: {
        ...Object.fromEntries(routing.locales.map((l) => [l, pageUrl(l, path)])),
        "x-default": pageUrl(routing.defaultLocale, path),
      },
    },
    openGraph: {
      type: "website",
      siteName: brandName,
      title,
      description,
      url: pageUrl(locale, path),
      locale: ogLocale[locale],
      alternateLocale: routing.locales
        .filter((l) => l !== locale)
        .map((l) => ogLocale[l]),
      images,
    },
    twitter: {
      card: "summary_large_image",
      title,
      description,
      images: [image],
    },
  };
}

/** Share image for a static page, generated at build time. */
export const ogImage = (locale: AppLocale, page: OgPage) =>
  `/og/${locale}/${page}.png`;

/** BreadcrumbList JSON-LD: Home → page. */
export function breadcrumbJsonLd(
  locale: AppLocale,
  homeLabel: string,
  crumbs: { name: string; path: string }[],
) {
  return {
    "@context": "https://schema.org",
    "@type": "BreadcrumbList",
    itemListElement: [{ name: homeLabel, path: "" }, ...crumbs].map(
      (c, i) => ({
        "@type": "ListItem",
        position: i + 1,
        name: c.name,
        item: pageUrl(locale, c.path),
      }),
    ),
  };
}
